// Parse and normalize Alibaba message payload
// Alibaba Trade Manager / messaging API format
const body = $input.item.json.body || $input.item.json;

// Support multiple payload formats:
// 1. Alibaba Trade Manager webhook
// 2. Manual forwarding (email/scraper)
// 3. API integration

let normalized;

if (body.data && body.data.type === 'trade_message') {
  // Alibaba Trade Manager format
  const msg = body.data;
  normalized = {
    source: 'alibaba',
    platform: 'trade_manager',
    conversation_id: `alibaba_${msg.sender_id}_${msg.thread_id || msg.inquiry_id}`,
    sender_id: msg.sender_id,
    sender_name: msg.sender_company || msg.sender_name || 'Unknown Seller',
    message: msg.content || msg.text,
    message_id: msg.message_id || `ali_${Date.now()}`,
    timestamp: msg.timestamp || new Date().toISOString(),
    metadata: {
      thread_id: msg.thread_id,
      inquiry_id: msg.inquiry_id,
      product_id: msg.product_id,
      product_name: msg.product_name,
      product_url: msg.product_url,
      seller_store_url: msg.store_url,
      seller_rating: msg.seller_rating,
      seller_years: msg.years_on_alibaba,
      seller_response_rate: msg.response_rate,
      price_mentioned: msg.price,
      moq: msg.moq,
      currency: msg.currency || 'USD'
    }
  };
} else if (body.from_email || body.forwarded) {
  // Email-forwarded Alibaba message
  const emailBody = body.body || body.content || body.text || '';
  const sellerMatch = emailBody.match(/from[:\s]+([^\n]+)/i);
  const priceMatch = emailBody.match(/(?:price|prix|\$|USD|EUR)\s*[:\s]*([\d.,]+)/i);
  const moqMatch = emailBody.match(/(?:MOQ|minimum|min\.?\s*order)\s*[:\s]*(\d+)/i);

  normalized = {
    source: 'alibaba',
    platform: 'email_forward',
    conversation_id: `alibaba_email_${body.from_email || body.sender || Date.now()}`,
    sender_id: body.from_email || body.sender || 'unknown',
    sender_name: sellerMatch ? sellerMatch[1].trim() : (body.from_name || body.sender_name || 'Unknown Seller'),
    message: emailBody,
    message_id: body.message_id || `ali_email_${Date.now()}`,
    timestamp: body.date || new Date().toISOString(),
    metadata: {
      original_subject: body.subject,
      price_detected: priceMatch ? parseFloat(priceMatch[1].replace(',', '')) : null,
      moq_detected: moqMatch ? parseInt(moqMatch[1]) : null,
      forwarded_from: body.from_email
    }
  };
} else {
  // Generic / manual format
  normalized = {
    source: 'alibaba',
    platform: body.platform || 'manual',
    conversation_id: body.conversation_id || `alibaba_manual_${body.seller_id || Date.now()}`,
    sender_id: body.seller_id || body.sender_id || 'unknown',
    sender_name: body.seller_name || body.sender_name || 'Unknown Seller',
    message: body.message || body.content || body.text || '',
    message_id: body.message_id || `ali_manual_${Date.now()}`,
    timestamp: body.timestamp || new Date().toISOString(),
    metadata: {
      product_name: body.product_name,
      product_url: body.product_url,
      seller_store_url: body.store_url,
      price: body.price ? parseFloat(body.price) : null,
      currency: body.currency || 'USD',
      moq: body.moq ? parseInt(body.moq) : null,
      quantity_needed: body.quantity ? parseInt(body.quantity) : null
    }
  };
}

return { json: normalized };

// Extract negotiation-relevant data from the message
const input = $input.item.json;
const message = (input.message || '').toLowerCase();
const meta = input.metadata || {};

// Detect prices in message
const pricePatterns = [
  /(?:USD|\$)\s*([\d.,]+)/gi,
  /([\d.,]+)\s*(?:USD|\$|dollars?)/gi,
  /(?:EUR|\u20ac)\s*([\d.,]+)/gi,
  /([\d.,]+)\s*(?:EUR|\u20ac|euros?)/gi,
  /(?:prix|price|cout|cost)\s*[:\s]*([\d.,]+)/gi,
  /(?:unit price|prix unitaire)\s*[:\s]*(?:USD|\$|EUR|\u20ac)?\s*([\d.,]+)/gi
];

let detectedPrices = [];
for (const pattern of pricePatterns) {
  let match;
  while ((match = pattern.exec(input.message)) !== null) {
    const price = parseFloat(match[1].replace(',', ''));
    if (price > 0 && price < 1000000) {
      detectedPrices.push(price);
    }
  }
}

// Detect quantities
const qtyPatterns = [
  /(?:qty|quantity|quantite|qte)\s*[:\s]*(\d+)/gi,
  /(\d+)\s*(?:pieces?|pcs|units?|unites?)/gi,
  /(?:MOQ|minimum)\s*[:\s]*(\d+)/gi
];

let detectedQuantities = [];
for (const pattern of qtyPatterns) {
  let match;
  while ((match = pattern.exec(input.message)) !== null) {
    detectedQuantities.push(parseInt(match[1]));
  }
}

// Detect shipping terms
const shippingTerms = ['FOB', 'CIF', 'EXW', 'DDP', 'DAP', 'FCA'];
const detectedIncoterm = shippingTerms.find(term => message.includes(term.toLowerCase()));

// Detect if seller is making an offer or responding to inquiry
const isOffer = /(?:offer|offre|best price|meilleur prix|special price|prix special|discount|remise|we can do|nous pouvons)/i.test(input.message);
const isCounterOffer = /(?:final price|dernier prix|cannot go lower|lowest|plus bas|last offer|derniere offre)/i.test(input.message);
const isAcceptance = /(?:deal|accord|accept|agreed|d'accord|ok pour|we agree)/i.test(input.message);
const isInquiryResponse = /(?:thank.*inquiry|merci.*demande|regarding your|suite a votre|in response)/i.test(input.message);

return {
  json: {
    ...input,
    negotiation_data: {
      detected_prices: detectedPrices,
      detected_quantities: detectedQuantities,
      detected_incoterm: detectedIncoterm || null,
      is_offer: isOffer,
      is_counter_offer: isCounterOffer,
      is_acceptance: isAcceptance,
      is_inquiry_response: isInquiryResponse,
      price_from_meta: meta.price_detected || meta.price || null,
      moq_from_meta: meta.moq_detected || meta.moq || null
    }
  }
};
